    var status = d.due ? tx('Due today: {stage}', { stage: stageName(d.next).toLowerCase() }) : d.skip ? tx('Held back: {why}', { why: lx(d.skip.text) }) : d.nextDate ? tx('Next letter due {date}', { date: dt(d.nextDate) }) : tx('Nothing overdue');
    var h = head(back, c.name, esc(m.title) + ' · ' + esc(LANG_NAME(m.lang)) + ' · ' + esc(status), '');
