      (m.paid.total > 0 ? '<p class="hint" style="margin-top:10px">' + esc(tx('Paid so far {x}', { x: eur2(m.paid.total) }) + (m.paid.costs > 0 || m.paid.interest > 0 ? ', ' + tx('of which costs {c}, interest {i} and principal {p}', { c: eur2(m.paid.costs), i: eur2(m.paid.interest), p: eur2(m.paid.principal) }) : ', ' + tx('all to the principal')) + '. ' + payOrderText()) + '</p>' : '') +
      '<p class="hint" style="margin-top:10px">' + esc(tx('Pay by {date} ({n} days).', { date: dt(m.deadline), n: S.payDays }) + ' ' + tx('Reference {ref}', { ref: m.reference }) + (m.rows.length > 1 ? ', ' + tx('the oldest invoice') : '') + '.' + (m.disputed.length ? ' ' + tx('Left out as disputed: {list}.', { list: m.disputed.map(function (i) { return i.no; }).join(', ') }) : '')) + '</p></section>';
    h += interestCalcCard(c, m);
