  function impLoad(name, text, encoding) {
    var p = E.parseCsv(text);
    if (!p.rows.length) { toast(tx('The file is empty.')); return; }
    var pr = E.detectPreset(p.rows[0]);
    imp = { name: name, encoding: encoding || 'utf-8', delimiter: p.delimiter, rows: p.rows, preset: pr ? pr.id : '', detected: pr ? pr.id : '', mapping: E.guessMapping(p.rows[0], null, pr), mode: 'add' };
    impCheck(); render();
  }
  function impPreset() { return E.IMPORT_PRESETS.filter(function (p) { return p.id === imp.preset; })[0] || null; }
  function impCheck() {
    var existing = {}; db.invoices.forEach(function (i) { existing[i.no] = 1; });
    var pr = impPreset();
    imp.result = E.buildImport(imp.rows, imp.mapping, { today: TODAY, existing: imp.mode === 'replace' ? {} : existing, aggregate: !!(pr && pr.aggregate) });
  }
  function impGo() {
    var res = imp.result; if (!res || res.errors.length || !res.items.length) return;
    if (imp.mode === 'replace' && noReplace()) { imp.mode = 'add'; toast(tx('Only an owner of this workspace can replace everyone’s data.')); render(); return; }
    var replace = imp.mode === 'replace', snap = snapshot(), created = 0;
    commit(tx('Imported {invoices} from {file}', { invoices: plural(res.items.length, 'invoice', 'invoices'), file: imp.name }) + (replace ? ' ' + tx('(demo data replaced)') : ''), function () {
      if (replace) { db.customers = []; db.invoices = []; db.actions = []; db.plans = []; db.demo = false; }
      var byVat = {}, byName = {}, n = db.customers.length;
      db.customers.forEach(function (c) { if (c.vatId) byVat[c.vatId.toUpperCase()] = c; byName[c.name.toLowerCase()] = c; });
      res.items.forEach(function (it, k) {
        var c = (it.vatId && byVat[it.vatId]) || byName[it.customer.toLowerCase()];
        if (!c) {
          created++;
          var country = it.country === 'HR' ? 'HR' : it.country || 'SI';
          c = { id: newId('c'), no: String(1001 + n++), name: it.customer, country: country, vatId: it.vatId, address: { street: '', postal: '', city: '' }, contact: { name: '', email: it.email || '', phone: it.phone || '' },
            segment: 'Imported', terms: Math.max(0, E.diffDays(it.issueDate, it.dueDate)), creditLimit: 0, onHold: false, language: country === 'HR' ? 'hr' : country === 'SI' ? 'sl' : 'en', notes: '', interest: { contractRate: null, cap: null }, bankAccounts: [] };
          db.customers.push(c); if (c.vatId) byVat[c.vatId] = c; byName[c.name.toLowerCase()] = c;
        }
        var inv = { id: newId('i') + k, no: it.no, customerId: c.id, issueDate: it.issueDate, dueDate: it.dueDate, amount: it.amount, payments: [], disputed: null, writtenOff: null, imported: TODAY };
        if (it.open < it.amount - 0.005) inv.payments.push({ date: E.minDate(it.dueDate, TODAY) < it.issueDate ? it.issueDate : E.minDate(it.dueDate, TODAY), amount: E.round2(it.amount - it.open), imported: true });
        db.invoices.push(inv);
      });
    });
    imp = null; render();
    toast(tx('Imported {invoices}', { invoices: plural(res.items.length, 'invoice', 'invoices') }) + (created ? ' ' + tx('and {customers}', { customers: plural(created, 'new customer', 'new customers') }) : ''), undoable(snap));
  }
  /** read an uploaded file as text: UTF-8, or Windows-1250 when it is not valid UTF-8 */
  function readFile(file, max, then) {
    if (file.size > max) return toast(tx('That file is over {n} MB.', { n: Math.round(max / 1048576) }));
    var rd = new FileReader();
    rd.onload = function () { var d = E.decodeBytes(new Uint8Array(rd.result)); then(d.text, d.encoding); };
    rd.onerror = function () { toast(tx('The file could not be read.')); };
    rd.readAsArrayBuffer(file);
  }

